parameters.jsonBody:
={{ (() => {
  const b = $json.body || {};
  const h = $json.headers || {};
  const clean = o => Object.fromEntries(Object.entries(o).filter(([k, v]) => v !== undefined && v !== null && v !== '' && !(Array.isArray(v) && v.length === 0)));
  const sha = v => v ? [String(v).trim().toLowerCase().hash('sha256')] : [];
  const parts = String(b.name || '').trim().split(/\s+/);
  const phone = String(b.telefon || '').replace(/\D/g, '').replace(/^00/, '').replace(/^0/, '49');
  const ip = String(h['x-forwarded-for'] || h['x-real-ip'] || '').split(',')[0].trim();
  return JSON.stringify({
    data: [clean({
      event_name: 'Lead',
      event_time: Number(b.event_time) || Math.floor(Date.now() / 1000),
      event_id: b.event_id,
      action_source: 'website',
      event_source_url: b.event_source_url,
      user_data: clean({
        em: sha(b.email),
        ph: phone ? [phone.hash('sha256')] : [],
        fn: sha(parts[0]),
        ln: sha(parts.length > 1 ? parts.slice(1).join(' ') : ''),
        ct: sha('frankfurt'),
        country: sha('de'),
        external_id: sha(b.email),
        client_ip_address: ip,
        client_user_agent: b.user_agent || h['user-agent'],
        fbc: b.fbc,
        fbp: b.fbp
      }),
      custom_data: clean({
        content_name: 'Rebuilding Mom & Dad',
        lead_type: b.anfrage_fuer,
        standort: b.standort,
        alter: b.alter,
        utm_source: b.utm_source,
        utm_medium: b.utm_medium,
        utm_campaign: b.utm_campaign,
        utm_content: b.utm_content,
        utm_term: b.utm_term
      })
    })]
  });
})() }}
